local FightRewardNode = Class('FightRewardNode')

function FightRewardNode:__init()
    self._data = nil
    self._size = nil
    self._isFillTitle = false
    self._itemLoader = nil
end

function FightRewardNode:__delete()
    self._data = nil
    self._size = nil
    self._isFillTitle = nil 
    self._itemLoader = nil
end

function FightRewardNode:Awake()
end

function FightRewardNode:RefreshNormal(data, size, isFillTitle)
    if not data then
        return
    end
    self._data = data
    self._size = size
    if isFillTitle then
        self._isFillTitle = true
    else
        self._isFillTitle = false
    end

    if not self._size then
        self._size = 1
    end

    local go = self:FillSelf()
    KTool.SetActive(self.controller.gameObject, true)
    return go                 --返回实例化出来的预设  做方法的特殊处理
end

function FightRewardNode:RefreshGetShow(isTrue)
    KTool.SetActive(self.hasGet, isTrue)
end

function FightRewardNode:FillSelf()
    local num 
    if self._data.numText then
        num = self._data.numText
    else
        num = checkNumber(self._data.num) > 0 and "x"..self._data.num or nil
    end
    
    local id = self._data.id
    if not id then
        id = self._data.goodsId
    end

    if not self._itemLoader then
        self._itemLoader = CS.Engine.Modules.ResourceModule.LoadBundleSync("Prefabs/Common/GoodNode.prefab", nil, true)
    end

    local go
    if self._itemLoader.IsSuccess then
        go = self.goodPar.transform:Find("Cell")
        if not go then 
            go = CfUtils.InstantiateGo(self._itemLoader.ResultObject, self.goodPar)
            go.name = "Cell"
        end
        if go then
            CfUtils.RefeshGoodGo(go, id, num, self._size)
        end
    end

    self:FillTitle(go)
    return go
end

function FightRewardNode:FillTitle(go)
    KTool.SetActive(self.title, false)

    if self._isFillTitle then 
        local state = 1
        if self._data.type == Constants.TeamShowRewardType.RegularType then
            state = 1
        elseif self._data.type == Constants.TeamShowRewardType.RareType then
            state = 2
        elseif self._data.type == Constants.TeamShowRewardType.FristType then
            state = 3
        elseif self._data.type == Constants.TeamShowRewardType.StarType then
            state = 4
        elseif self._data.type == Constants.TeamShowRewardType.ActivityType then
            state = 5
        end

        local scr = CfUtils.GetLuaScr(go, "Game.Behaviours.GoodNodeMB")
        if scr then
            scr:SetBonusText(RewardConfMgr:GetInstance():GetTeamShowRewardTagName(self._data.type), state)
        end
    else
    end
end

function FightRewardNode:OnDestroy()
    if not isNull(self._itemLoader) then
        self._itemLoader:Release()
        self._itemLoader = nil
    end
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return FightRewardNode
